function unitMods(u, kind){
  const A = army(), out = [], srcs = dmSources(A, u);
  const of = g => srcs.filter(S => S.grp === g);
  const core = [];
  // (Lance for its [LANCE] weapons; Plunging Fire for a TOWERING unit, not AIRCRAFT: BOXES played, the Damage tab's own)
  const played = (name, text) => { const key = DM_KEY.c(name, text), o = (D.boxes || {})[key]; return o && o.played ? { grp:'unit', name, rule:name, key, core:true } : null; };
  if([].concat(u.ranged || [], u.melee || []).some(w => (w.kw || []).some(k => /^lance$/i.test(k))) && D.rules.Lance) core.push(played('Lance', D.rules.Lance));
  if(hasKw(u, 'Towering') && !hasKw(u, 'Aircraft') && D.rules['Plunging Fire']) core.push(played('Plunging Fire', D.rules['Plunging Fire']));
  const dmg = (u.abilities || []).filter(ab => /^Damaged: /i.test(ab.name)).map(ab => ({ grp:'unit', name:ab.name, key:DM_KEY.a(ab), ab, src:u, damaged:true }));
  // (the core stratagems, every unit's, are on the Stratagems tab: the footnotes name the list's detachments' stratagems)
  const listStrat = S => !S.strat || (S.s && S.s.src !== 'Core');
  for(const S of of('unit').filter(S => !S.core).concat(dmg, of('unit').filter(S => S.core).map(S => Object.assign({ rule:S.name }, S)), of('army'), core.filter(Boolean), of('other'), of('strat')).filter(listStrat)){
    const o = (D.boxes || {})[S.key] || {};
    for(const b of o.b || []){
      if(S.reachOnly ? !(b.reach && dmReaches(b.reach, u)) : b.reach ? !dmReaches(b.reach, u) || (S.grp === 'unit' && b.notSelf) : S.grp === 'other') continue;
      if(b.kind !== 'all' && b.kind !== kind) continue;
      const m = fnLine(S, b, u, kind, S.ab);
      if(m) out.push(m);
    }
    // (words about its attacks no catalogue effect reads, BOXES nc atk: "not counted here: see the rule", the name opening them; not
    // another unit's (its words may not reach this one), not a Damaged band's (its band says so))
    if(!S.damaged && S.grp !== 'other' && (o.nc || []).some(x => x.atk) && !out.some(x => x.key === S.key && x.ncLine)) out.push(Object.assign({ kind:'all', when:'', note:FN_NC, who:'', from:S.name, key:S.key, box:null, ncLine:true },
      S.rule ? { rule:S.rule } : {}, S.strat ? { strat:S.strat, cp:S.cp } : {}));
  }
  return out;
}

function fnLine(S, b, u, kind, ab){
  const E = WH_EFFECTS, sc = b.scope || {};
  const ws = sc.weapon || sc.wkw || sc.part ? fnWeapons(u, kind, sc) : null;
  if(ws && !ws.length) return null;   // (for weapons this kind of attack has not)
  // (not an effect the list printed into the weapons, marked + there; nor a weapon ability every weapon it reaches has already: Waaagh!'s
  // [ASSAULT] for a unit whose ranged weapons all have it)
  const its = ws || weaponItems(kind === 'ranged' ? u.ranged || [] : u.melee || []);
  const hasAll = l => /^\[.+\]$/.test(l) && its.length && its.every(it => it.profiles.every(w => (w.kw || []).some(k => '[' + String(k).toUpperCase() + ']' === l)));
  // (nor, for melee attacks, an effect only ranged attacks have: range, a set BS, [ASSAULT], [HEAVY], [INDIRECT FIRE], [PISTOL])
  const baked = S.baked || [], keep = fx => (fx || []).filter(([id, p]) => !dmBaked(baked, id, p) && !hasAll(E.fxLabel([[id, p]])) && !(kind === 'melee' && FN_RANGED.has(id)));
  // (a keyword or wargear of the unit the box needs, "If this model has the TOZEENTCH keyword": the unit's keywords and weapons say it)
  const wn = [].concat(u.ranged || [], u.melee || []).flatMap(w => [w.name, w.group]).filter(Boolean).map(x => String(x).toLowerCase());
  if((b.on || []).some(([id, p]) => (id === 'selfKw' && !hasKw(u, p)) || (id === 'selfGear' && !p.every(g => wn.some(n => n.startsWith(String(g).toLowerCase())))))) return null;
  // (the unit that gives it: its name, or the model of an attached unit whose ability it is)
  const gab = S.src && S.src !== u ? (S.src.abilities || []).find(x => x.name === S.name) : null;
  const giver = S.src && S.src !== u ? (gab && gab.who && S.src.leads && charsOf(S.src).some(c => c.name === gab.who) ? gab.who : S.src.short || S.src.name) : '';
  const own = S.grp === 'unit' && b.mark === 'aura';
  // (none: every attack of its kind; a stratagem's line names it with its cost instead)
  // (a stratagem's one phase, from its derived phases and turn: "Your Shooting phase", "Fight phase", the detachment's line says it once)
  const sPh = S.s && (S.s.phases || []).length === 1 ? (T => (T === 'your' ? 'Your ' : T === 'opp' ? 'Your opponent’s ' : '') + PHASE_NAME[S.s.phases[0]] + ' phase')(phTurn(S.s, S.s.phases[0])) : '';
  // (its conditions, each said; one that is only GW's words, quoted, is said too beside another, so the line is never wider than GW's
  // rule. A box whose only conditions are quoted says "If (see the rule)" (FN_IF), the rule's name opening its words: the owner's
  // decision, 31 Oct, never shown as always on. "Every attack": no condition at all, in the box or its options)
  const quoted = ([id]) => !!(E.COND[id] && E.COND[id].quoted), on = b.on || [];
  const conds = on => (on || []).map(([id, p]) => fnCond(id, p, u, giver, own)).join(' · ');
  const onlyQ = on.length && on.every(quoted);
  const anyPickOn = (b.pick || []).some(p => (p.on || []).length || p.part);
  const when = [sPh, onlyQ ? FN_IF : conds(on)].filter(Boolean).join(', ') || (S.strat || anyPickOn ? '' : b.kind === 'ranged' ? 'Every ranged attack' : b.kind === 'melee' ? 'Every melee attack' : 'Every attack');
  const part = x => x && x.fx && x.fx.length ? ' (' + (conds(x.on) ? conds(x.on) + ': ' : '') + E.fxLabel(x.fx) + ')' : '';
  let note, fx = null;
  if(b.pick){ const ps = b.pick.map(p => Object.assign({}, p, { fx:keep(p.fx) })).filter(p => p.fx.length);
    if(!ps.length) return null;
    const bOn = new Set((b.on || []).map(x => JSON.stringify(x)));
    note = ps.map(p => { const pon = (p.on || []).filter(x => !bOn.has(JSON.stringify(x)));
      return (p.name !== E.fxLabel(p.fx) ? p.name + ': ' : '') + E.fxLabel(p.fx) + (conds(pon) ? ' (' + conds(pon) + ')' : '') + part(p.part); }).join(' · ');
    note = 'one of: ' + note; }
  else { fx = keep(b.fx); if(!fx.length) return null; note = E.fxLabel(fx) + part(b.part); }
  const who = ws ? [...new Set(ws.map(itemName))].join(', ') : sc.models === 'char' ? 'CHARACTER models' : sc.models === 'nonchar' ? 'Models (not CHARACTER)' : sc.models === 'one' ? 'One model' :
    sc.part ? sc.part + ' models' : sc.models === 'model' && ab && ab.who && u.leads ? ab.who : '';
  const m = { kind:b.kind, when, note, who, from:S.name, box:b, key:S.key };
  if(S.rule) m.rule = S.rule;
  if(S.strat){ m.strat = S.strat; m.cp = S.cp; }
  if(S.src && S.src !== u) m.src = S.src;
  if(S.damaged) m.damaged = true;
  // a box for one weapon's characteristics, nothing else: that weapon's row shows it ("8 (+6)", "6/7"), its condition under it
  // (not a stratagem's, nor an ability's the unit uses, "if it uses this ability": the player's to use, as a one-off is: oneOffMod)
  if(fx && ws && ws.length === 1 && !ws[0].group && !S.damaged && !S.strat && !(b.on || []).some(x => x[0] === 'used') && fx.every(([id]) => FN_ROW[id] || FN_SET[id])){
    m.weapon = ws[0].profiles[0].name; m.set = Object.fromEntries(fx.map(([id, p]) => FN_ROW[id] ? [FN_ROW[id], '+' + String(p).toUpperCase()] : [FN_SET[id], String(p)])); m.note = ''; m.who = ''; }
  return m;
}

function fnCond(id, p, u, giver, own){
  const C = WH_EFFECTS.COND[id];
  if(id === 'aura') return own ? 'Own aura' : giver ? 'Within ' + p + '" of ' + giver : C.label(p);
  if(id === 'selected' && giver) return 'Selected by ' + giver;
  if(id === 'belowStarting' && modelCount(u) === 1) return 'Lost any wounds (' + C.label(p) + ')';
  if(id === 'belowHalf' && modelCount(u) === 1) return halfBelow(u) + ' or fewer wounds left (' + C.label(p) + ')';
  return C ? C.label(p) : id;
}

const fnWeapons = (u, kind, sc) => { const lc = x => String(x || '').toLowerCase().replace(/[’']/g, "'");
  return weaponItems(kind === 'ranged' ? u.ranged || [] : u.melee || []).filter(it => (!sc.weapon || it.profiles.some(p => [p.name, it.group, itemName(it)].some(x => lc(x) === sc.weapon || lc(x).startsWith(sc.weapon))))
    && (!sc.wkw || it.profiles.some(p => (p.kw || []).some(k => String(k).toUpperCase() === sc.wkw || String(k).toUpperCase().startsWith(sc.wkw + ' '))))
    && (!sc.part || lc(it.who).startsWith(lc(sc.part).replace(/s$/, '')))); };

function abilityGaps(u, ab){
  const found = [];
  if(ab.na) return found;
  const r = readingsOfUnit(u, ab), all = r.attackSaid + ' | ' + r.defSaid;
  const hasKw = k => (u.kw || []).some(x => x.toLowerCase() === k.toLowerCase() || x.toLowerCase() === 'faction: ' + k.toLowerCase());
  for(const { s, pre } of sentenceCtx(ab.text)){
    // (an option for a keyword the unit does not have: "If this model has the TZEENTCH keyword" on a Daemon Prince of Khorne)
    const kwIf = /\b[Ii]f this (?:model|unit) has the ([A-Z][A-Z’' -]+?) keyword/.exec(s);
    if(kwIf && !hasKw(kwIf[1].trim())) continue;
    const b = bonusOf(s), miss = [];
    let check = null;
    // (an attack bonus: the unit's footnotes and the Damage tab's boxes are data.js BOXES, made from these words by script; verify/evidence.js
    // G4 holds every attack effect of them to a box or to its words listed as not counted. Only the defence side is a reading)
    // (a defence is said by a "When targeted" reading, not by an attack footnote that happens to say "damage" or "AP")
    const dmiss = b.def.filter(id => !covers(id, r.defSaid + ' | ' + r.marks.join(' | '), DEFENCE));
    if(dmiss.length){ check = check || 'defence'; miss.push(...dmiss); }
    if(check) found.push({ check, sentence:s, bonus:[...new Set(miss)] });
  }
  return found;
}

function resolveArmies(armies, sheets, order, factions, opts){
  opts = opts || {}; factions = factions || {};
  var ROWS = ['stats', 'ranged', 'melee', 'abilities'], READ = ['guard'];
  var FPK = ["gistOf","defOf","readOf","readBy","listWhy"], RHIDE = ['readOf', 'readBy', 'listWhy'].filter(function(k){ return (opts.keep || []).indexOf(k) < 0; });
  var HIDE = ['ds', 'over', 'of', 'why', 'own', 'faction', 'bsId'].concat(FPK, ["points","composition","options","aiStatus"]).filter(function(k){ return (opts.keep || []).indexOf(k) < 0; });
  function put(o, x){ for(var k in x) if(HIDE.indexOf(k) < 0){ if(x[k] === null) delete o[k]; else o[k] = x[k]; } return o; }
  function copy(x){ return JSON.parse(JSON.stringify(x)); }   // each unit its own copy of a datasheet's values
  function sorted(o, keys){ var out = {}, i, k; for(i = 0; i < keys.length; i++) if(keys[i] in o) out[keys[i]] = o[keys[i]]; for(k in o) if(!(k in out)) out[k] = o[k]; return out; }
  function rowOf(part, kind, name, group){ var rows = (part && part[kind]) || [], j; for(j = 0; j < rows.length; j++) if(rows[j].name === name && (group === undefined || (rows[j].group || null) === group)) return j; return -1; }
  function find(parts, kind, r){
    var name = kind === 'stats' ? String(r.name).replace(/ ×\d+$/, '') : r.name, i, j;
    // (a row by its name and, where its datasheet has two rows of the name, the group the entry names: the Bloodthirster's "strike" of its
    // Great axe of Khorne, not of its Axe of Khorne)
    var g = kind === 'stats' ? undefined : r.group;
    if(r.of !== undefined) return { p:r.of, j:rowOf(parts[r.of], kind, name, g) };
    for(i = 0; i < parts.length; i++) if(parts[i].name === r.who && (j = rowOf(parts[i], kind, name, g)) >= 0) return { p:i, j:j };
    for(i = 0; i < parts.length; i++) if((j = rowOf(parts[i], kind, name, g)) >= 0) return { p:i, j:j };
    return { p:-1, j:-1 };
  }
  // names alike in case and apostrophe (New Recruit's "Martial Ka'tah", Wahapedia's "Martial Ka’tah")
  function nm(s){ return String(s).toLowerCase().replace(/[’‘]/g, "'"); }
  function has(list, x){ for(var i = 0; i < (list || []).length; i++) if(nm(list[i]) === nm(x)) return true; return false; }
  function meets(n, u){ return !n || (!n.all || n.all.every(function(k){ return has(u.kw, k); })) && (!n.any || n.any.some(function(k){ return has(u.kw, k); }))
    && !(n.none || []).some(function(k){ return has(u.kw, k); }) && (!n.rule || n.rule.some(function(r){ return has(u.rules, r); })); }
  // the readings of one kind a unit has: the rows' (each with where it is from, for the trace), then the entry's
  function readings(a, u, out, ids, parts, kind){
    var F = factions[a.faction] || {}, dets = (a.detachments || []).map(function(d){ return (F.detachments || {})[d]; }).filter(Boolean), t = [], enh = null;
    function take(x, at){ ((x && x[kind]) || []).forEach(function(m, j){ t.push({ m:m, at:at, j:j }); }); }
    (F.armyRules || []).forEach(function(r){ if(has(out.rules, r.name)) take(r, null); });
    parts.forEach(function(p, i){ take(p, ids[i]); });
    dets.forEach(function(d){ (d.enhancements || []).forEach(function(e){ if(!enh && (e.name === out.enhancement || e.name === out.upgrade)) take(enh = e, null); }); });
    dets.forEach(function(d){ [d.rule].concat(d.moreRules || []).forEach(function(r){ if(r && meets(r.needs, out)) take(r, null); }); });
    var own = u[kind], list = [];
    if(own === null) list = [];
    else if(!own) list = t;
    else if(own.some(function(x){ return typeof x === 'string'; })) own.forEach(function(x, e){ if(typeof x !== 'string') list.push({ m:x, at:null, e:e }); else t.forEach(function(y, i){ if(y.m.from === x) list.push(i === t.findIndex(function(z){ return z.m.from === x; }) ? Object.assign({ e:e }, y) : y); }); });
    else list = t.concat(own.map(function(x, e){ return { m:x, at:null, e:e }; }));
    return list.map(function(y, n){ var m = copy(y.m); RHIDE.forEach(function(k){ delete m[k]; }); if(opts.trace) opts.trace(a, u, kind, n, y.at, y.at ? y.j : -1, y.e); return m; });
  }
  return armies.map(function(a){
    return Object.assign({}, a, { units:a.units.map(function(u){
      if(!u.ds) return u;
      var ids = [].concat(u.ds), parts = ids.map(function(id){ if(!sheets[id]) throw new Error('data.js: ' + a.id + '/' + u.id + ' names no datasheet ' + id); return sheets[id]; });
      var out = {}, k, rest = {};
      for(k in parts[0]) if(ROWS.indexOf(k) < 0 && READ.indexOf(k) < 0 && HIDE.indexOf(k) < 0) out[k] = copy(parts[0][k]);
      for(k in u) if(ROWS.indexOf(k) < 0 && READ.indexOf(k) < 0) rest[k] = u[k];
      put(out, rest); if(u.over) put(out, u.over);
      ROWS.forEach(function(kind){
        var list;
        if(kind in u){ if(u[kind] === null){ delete out[kind]; return; } list = u[kind]; }
        else if(parts.length === 1 && parts[0][kind]) list = parts[0][kind].map(function(r){ return { name:r.name }; });
        else return;
        out[kind] = list.map(function(r, n){
          var at = find(parts, kind, r);
          if(at.j < 0){ if(opts.trace) opts.trace(a, u, kind, n, null, -1); return put({}, r); }
          if(opts.trace) opts.trace(a, u, kind, n, ids[at.p], at.j);
          var ds = parts[at.p][kind][at.j], row = put({}, copy(ds)); put(row, r); if(r.over) put(row, r.over);
          // (for --expand: the datasheet's own value of a stat a rule of the list changed, own, so --write gives it back)
          if((kind === 'stats' || kind === 'ranged' || kind === 'melee') && r.from && (opts.keep || []).indexOf('own') >= 0){ var own = {}, f; for(f in r.from) if(f in ds && ds[f] !== r[f]) own[f] = ds[f]; for(f in own){ row.own = own; break; } }
          return sorted(row, order[kind] || []);
        });
      });
      READ.forEach(function(kind){ var l = readings(a, u, out, ids, parts, kind); if(l.length) out[kind] = l; });
      return sorted(out, order.unit || []);
    }) });
  });
}
